const KEY='persona-atlas-v2';
const seed={research:[
{id:'r1',title:'Research Report: Lost & Found Pets in Lisbon',type:'Secondary research synthesis',date:'2026-10-09',scope:'Lisbon municipality',status:'preliminary',evidence:'Review of Facebook groups, public platforms, one public lost-pet case and persona research requirements.',limits:'Facebook content access was restricted. Platform counts require geographic, period and duplicate verification.',personaIds:['owner','finder','spotter']},
{id:'r2',title:'Public case: Guai-Guai',type:'Public case',date:'2026-09-08',scope:'Parque das Nações, Lisbon',status:'preliminary',evidence:'The public appeal included animal type, name, location, disappearance date, description, microchip status and behaviour information.',limits:'One case cannot establish a behavioural pattern. Outcome was not confirmed.',personaIds:['owner']},
{id:'r3',title:'Preliminary platform listing review',type:'Platform review',date:'2026-10-09',scope:'Geographic filters not confirmed',status:'preliminary',evidence:'The review observed 432 Encontra-me listings and approximately 525 FindMyPet listings in selected results.',limits:'Counts are not unique Lisbon cases. Duplicates, periods and listing categories require verification.',personaIds:[]},
{id:'r4',title:'Class 2 qualitative research plan',type:'Research plan',date:'2026-10-08',scope:'Lisbon municipality',status:'planned',evidence:'Planned interviews include Owners, Finders, Spotters and people who did not intervene or stopped partway.',limits:'No interviews have been conducted. Segments remain provisional.',personaIds:['owner','finder','spotter']}
],personas:[
{id:'owner',label:'Active Owner',role:'Owner',situation:'A pet owner coordinating a search after a disappearance.',version:1,claims:[{category:'Goal',text:'Find the missing pet and identify credible leads.',status:'hypothesis',sources:['r1']},{category:'Observed behaviour',text:'Lost-pet reports can contain photographs, location and identifying details.',status:'observed',sources:['r1','r2']},{category:'Possible need',text:'A way to coordinate information distributed across several channels.',status:'hypothesis',sources:['r1']}]},
{id:'finder',label:'Temporary Finder',role:'Finder',situation:'A person who has taken temporary responsibility for a found animal.',version:1,claims:[{category:'Goal',text:'Keep the animal safe while trying to locate its owner.',status:'hypothesis',sources:['r4']},{category:'Observed behaviour',text:'Found-animal reports may use photographs, location and descriptive information.',status:'observed',sources:['r1']},{category:'Open question',text:'How long can the person continue caring for the animal?',status:'hypothesis',sources:['r4']}]},
{id:'spotter',label:'Quick Spotter',role:'Spotter',situation:'A passer-by who sees a possibly lost animal but does not take it in.',version:1,claims:[{category:'Goal',text:'Share useful sighting information with limited involvement.',status:'hypothesis',sources:['r4']},{category:'Observed behaviour',text:'A sighting report can include a photograph and approximate location.',status:'interpretation',sources:['r1']},{category:'Open question',text:'Why does the person continue, limit or stop their involvement?',status:'hypothesis',sources:['r4']}]}
],drafts:[],history:[{id:'h1',date:'2026-10-10',title:'Created three proto-personas',detail:'Added Active Owner, Temporary Finder and Quick Spotter as hypotheses.',source:'Research report and research plan',status:'accepted'}]};
let state=load(),view='personas',activePersona=null,draftFilter='pending';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function clone(x){return JSON.parse(JSON.stringify(x))}function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?.personas?x:clone(seed)}catch{return clone(seed)}}function save(){localStorage.setItem(KEY,JSON.stringify(state))}function uid(){return crypto.randomUUID()}function now(){return new Date().toISOString().slice(0,10)}function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function per(id){return state.personas.find(x=>x.id===id)}function src(id){return state.research.find(x=>x.id===id)}function date(d){return new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00'))}
function render(){counts();personas();research();drafts();history();selects()}
function counts(){const pending=state.drafts.filter(x=>x.status==='pending').length,claims=state.personas.reduce((n,p)=>n+p.claims.length,0);$('#personaCount').textContent=state.personas.length;$('#researchCount').textContent=state.research.length;$('#draftCount').textContent=pending;$('#statPersonas').textContent=state.personas.length;$('#statResearch').textContent=state.research.length;$('#statDrafts').textContent=pending;$('#statClaims').textContent=claims}
function personas(){const q=$('#search').value.toLowerCase(),list=state.personas.filter(p=>JSON.stringify(p).toLowerCase().includes(q));$('#personaGrid').innerHTML=list.length?list.map(p=>{const c=p.claims.find(x=>x.category==='Goal')||p.claims[0],n=new Set(p.claims.flatMap(x=>x.sources)).size;return `<article class="persona" data-persona="${p.id}"><div class="phead"><span class="avatar">${esc(p.role[0])}</span><div><h3>${esc(p.label)}</h3><span class="pill">${esc(p.role)} · proto-persona</span></div></div><p>${esc(p.situation)}</p><div class="preview"><span>${c?esc(c.category):'Evidence status'}</span><b>${c?esc(c.text):'Insufficient evidence'}</b></div><div class="pfoot"><span>Version ${p.version}.0</span><em>${n} linked source${n===1?'':'s'}</em></div></article>`}).join(''):'<div class="empty">No cards match this search.</div>';$$('[data-persona]').forEach(x=>x.onclick=()=>openPersona(x.dataset.persona))}
function research(){const f=$('#researchFilter').value,list=state.research.filter(r=>f==='all'||r.status===f).sort((a,b)=>b.date.localeCompare(a.date));$('#researchList').innerHTML=list.map(r=>`<article class="item"><span class="ico">≋</span><div><h3>${esc(r.title)}</h3><p>${esc(r.evidence)}</p><div class="meta">${esc(r.type)} · ${date(r.date)} · ${esc(r.scope)}<br>Limitation: ${esc(r.limits)}</div></div><span class="status ${r.status}">${r.status}</span></article>`).join('')||'<div class="empty">No research records in this status.</div>'}
function drafts(){const list=state.drafts.filter(d=>d.status===draftFilter).sort((a,b)=>b.created.localeCompare(a.created));$('#draftList').innerHTML=list.length?list.map(d=>`<article class="item draft"><span class="ico">✦</span><div class="draft-card"><h3>${esc(d.card.label)} · generated card v${d.card.version}.0</h3><dl><dt>Role</dt><dd>${esc(d.card.role)}</dd><dt>Situation</dt><dd>${esc(d.card.situation)}</dd><dt>Goal</dt><dd>${esc(d.card.goal)}</dd><dt>Behaviours</dt><dd>${esc(d.card.behaviours.join(' · '))}</dd><dt>Needs</dt><dd>${esc(d.card.needs.join(' · '))}</dd><dt>Missing evidence</dt><dd>${esc(d.card.missing.join(' · '))}</dd></dl><div class="meta">Generated from ${d.sourceIds.map(x=>esc(src(x)?.title)).join('; ')}</div></div><div class="side-actions"><span class="status ${d.status}">${d.status}</span>${d.status==='pending'?`<button class="btn" data-review="${d.id}">Review draft</button>`:''}</div></article>`).join(''):'<div class="empty">No generated cards in this state.</div>';$$('[data-review]').forEach(x=>x.onclick=()=>review(x.dataset.review))}
function history(){$('#historyList').innerHTML=state.history.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(h=>`<article class="item"><span class="ico">↺</span><div><h3>${esc(h.title)}</h3><p>${esc(h.detail)}</p><div class="meta">${date(h.date)} · Source: ${esc(h.source)}</div></div><span class="status ${h.status}">${h.status}</span></article>`).join('')}
function selects(){const ps=state.personas.map(p=>`<option value="${p.id}">${esc(p.label)}</option>`).join('');$('#rPersona').innerHTML='<option value="">Unlinked</option>'+ps}
function openPersona(id){activePersona=id;const p=per(id),groups={};p.claims.forEach(c=>(groups[c.category]??=[]).push(c));$('#drawerBody').innerHTML=`<div class="drawerbody"><div class="identity"><span class="avatar">${esc(p.role[0])}</span><div><h2>${esc(p.label)}</h2><p>${esc(p.situation)}</p><span class="version">Proto-persona · Version ${p.version}.0</span></div></div>${Object.entries(groups).map(([g,cs])=>`<section class="group"><h3>${esc(g)}</h3>${cs.map(c=>`<div class="claim ${c.status==='hypothesis'?'hypothesis':''}">${esc(c.text)}<small>${esc(c.status)} · ${c.sources.map(x=>'Source: '+esc(src(x)?.title||'Missing')).join(' · ')}</small></div>`).join('')}</section>`).join('')}<div class="insufficient"><b>Do not assume:</b> demographics, quotations, motivations or behaviours missing from linked research.</div></div>`;$('#drawer').classList.add('open');$('#backdrop').classList.add('open')}
function closeDrawer(){$('#drawer').classList.remove('open');$('#backdrop').classList.remove('open')}function showDialog(id){$(id).showModal()}function closeDialogs(){$$('dialog[open]').forEach(d=>d.close())}
function switchView(name){view=name;$$('.view').forEach(x=>x.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===name));$('#pageTitle').textContent={personas:'Personas',research:'Research',drafts:'Generated drafts',history:'History'}[name];$('#mainAction').textContent={personas:'New persona',research:'Add research',drafts:'Generate all cards',history:'Export history'}[name]}
function generateCard(pid,extraClaims=[]){const p=per(pid),claims=[...p.claims,...extraClaims],sourceIds=[...new Set(claims.flatMap(c=>c.sources))],field=c=>claims.filter(x=>x.category===c);const goal=field('Goal')[0]?.text||'Insufficient evidence';const behaviours=field('Observed behaviour').map(x=>x.text);const needs=field('Possible need').map(x=>x.text);const questions=field('Open question').map(x=>x.text);const missing=[];if(!behaviours.length)missing.push('Observed behaviour');if(!needs.length)missing.push('Needs');if(!questions.length)missing.push('Open questions');missing.push('Motivation','Demographics','Direct quotation');return {label:p.label,role:p.role,situation:p.situation,goal,behaviours:behaviours.length?behaviours:['Insufficient evidence'],needs:needs.length?needs:['Insufficient evidence'],missing:[...new Set(missing)],version:p.version+1,generatedAt:now(),sourceCount:sourceIds.length}}
function generate(pid){const existing=state.drafts.find(x=>x.personaId===pid&&x.status==='pending');if(existing){toast('A pending draft already exists');return}const sourceIds=[...new Set(per(pid).claims.flatMap(c=>c.sources))];state.drafts.unshift({id:uid(),personaId:pid,card:generateCard(pid),sourceIds,status:'pending',created:now()});state.history.unshift({id:uid(),date:now(),title:`Generated English card for ${per(pid).label}`,detail:'Created a draft from linked claims. No research record was changed.',source:sourceIds.map(x=>src(x)?.title).join('; '),status:'pending'});save();render();switchView('drafts');closeDrawer();toast('English card draft generated')}
function generateAll(){state.personas.forEach(p=>{if(!state.drafts.some(d=>d.personaId===p.id&&d.status==='pending')){const ids=[...new Set(p.claims.flatMap(c=>c.sources))];state.drafts.unshift({id:uid(),personaId:p.id,card:generateCard(p.id),sourceIds:ids,status:'pending',created:now()})}});save();render();switchView('drafts');toast('English card drafts generated')}
function review(id){const d=state.drafts.find(x=>x.id===id),c=d.card;$('#reviewId').value=id;$('#reviewNote').value='';$('#reviewCard').innerHTML=`<h3>${esc(c.label)}</h3><dl><dt>Role</dt><dd>${esc(c.role)}</dd><dt>Situation</dt><dd>${esc(c.situation)}</dd><dt>Goal</dt><dd>${esc(c.goal)}</dd><dt>Behaviours</dt><dd>${esc(c.behaviours.join(' · '))}</dd><dt>Needs</dt><dd>${esc(c.needs.join(' · '))}</dd><dt>Insufficient evidence</dt><dd>${esc(c.missing.join(' · '))}</dd></dl>`;showDialog('#reviewDialog')}
function decide(ok){const d=state.drafts.find(x=>x.id===$('#reviewId').value),note=$('#reviewNote').value.trim();if(!note){toast('Add a review note');return}d.status=ok?'accepted':'rejected';d.reviewNote=note;d.reviewed=now();if(ok){const p=per(d.personaId);if(d.suggestedClaim)p.claims.push(d.suggestedClaim);p.version=d.card.version;state.history.unshift({id:uid(),date:now(),title:`Approved ${p.label} version ${p.version}.0`,detail:'Researcher approved the generated English card. Previous version preserved.',source:d.sourceIds.map(x=>src(x)?.title).join('; '),status:'accepted'})}else state.history.unshift({id:uid(),date:now(),title:`Rejected generated card for ${per(d.personaId).label}`,detail:note,source:d.sourceIds.map(x=>src(x)?.title).join('; '),status:'rejected'});save();render();closeDialogs();toast(ok?'New persona version approved':'Draft rejected and recorded')}
function addPersona(e){e.preventDefault();state.personas.push({id:uid(),label:$('#pLabel').value.trim(),role:$('#pRole').value,situation:$('#pSituation').value.trim(),version:1,claims:[]});save();render();closeDialogs();e.target.reset();toast('Proto-persona created')}
function addResearch(e){e.preventDefault();const pid=$('#rPersona').value,cat=$('#rCategory').value,r={id:uid(),title:$('#rTitle').value.trim(),type:$('#rType').value,date:$('#rDate').value,scope:$('#rScope').value.trim(),status:$('#rStatus').value,evidence:$('#rEvidence').value.trim(),limits:$('#rLimit').value.trim()||'No limitation recorded.',personaIds:pid?[pid]:[]};state.research.push(r);if(pid&&cat!=='none'){const suggestedClaim={category:cat,text:r.evidence,status:r.status==='verified'?'observed':'hypothesis',sources:[r.id]},p=per(pid);state.drafts.unshift({id:uid(),personaId:pid,card:generateCard(pid,[suggestedClaim]),sourceIds:[...new Set([...p.claims.flatMap(c=>c.sources),r.id])],suggestedClaim,status:'pending',created:now()})}state.history.unshift({id:uid(),date:now(),title:'Added immutable research record',detail:`Added “${r.title}”. Existing records were not modified.${pid&&cat!=='none'?' A persona update draft awaits review.':''}`,source:r.title,status:'accepted'});save();render();closeDialogs();e.target.reset();$('#rDate').value=now();$('#rScope').value='Lisbon municipality';toast(pid&&cat!=='none'?'Research preserved; update draft created':'Research record preserved')}
function query(){const p=per(activePersona);$('#queryTitle').textContent=`Query ${p.label}`;$('#thread').innerHTML='<div class="msg">Ask a research question. Answers use linked claims only.<small>Evidence synthesis, not a real user</small></div>';showDialog('#queryDialog')}
function answer(q){const p=per(activePersona),s=q.toLowerCase();let cs;if(/goal|achieve/.test(s))cs=p.claims.filter(x=>x.category==='Goal');else if(/behav|do|action|channel|report/.test(s))cs=p.claims.filter(x=>x.category==='Observed behaviour');else if(/need|help|support/.test(s))cs=p.claims.filter(x=>x.category==='Possible need');else if(/motivation|why|demographic|quote|trust/.test(s))cs=[];else cs=p.claims.filter(x=>x.status==='observed');if(!cs.length)return {text:'Insufficient evidence. Linked research does not support an answer.',sources:[]};return{text:cs[0].text,sources:cs[0].sources.map(x=>src(x)?.title)}}
function exportData(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download=`persona-atlas-${now()}.json`;a.click();URL.revokeObjectURL(url);toast('Workspace exported')}
let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
$$('.nav').forEach(x=>x.onclick=()=>switchView(x.dataset.view));$$('.close').forEach(x=>x.onclick=closeDialogs);$$('.tab').forEach(x=>x.onclick=()=>{$$('.tab').forEach(y=>y.classList.remove('active'));x.classList.add('active');draftFilter=x.dataset.filter;drafts()});$('#search').oninput=personas;$('#researchFilter').onchange=research;$('#closeDrawer').onclick=$('#backdrop').onclick=closeDrawer;$('#queryBtn').onclick=query;$('#generateBtn').onclick=()=>generate(activePersona);$('#generateAll').onclick=generateAll;$('#addResearch').onclick=()=>showDialog('#researchDialog');$('#exportBtn').onclick=exportData;$('#mainAction').onclick=()=>{if(view==='personas')showDialog('#personaDialog');else if(view==='research')showDialog('#researchDialog');else if(view==='drafts')generateAll();else exportData()};$('#personaForm').onsubmit=addPersona;$('#researchForm').onsubmit=addResearch;$('#reviewForm').onsubmit=e=>{e.preventDefault();decide(true)};$('#rejectBtn').onclick=()=>decide(false);$('#queryForm').onsubmit=e=>{e.preventDefault();const q=$('#queryInput').value.trim(),a=answer(q);$('#thread').insertAdjacentHTML('beforeend',`<div class="msg user">${esc(q)}</div><div class="msg">${esc(a.text)}<small>${a.sources.length?'Sources: '+a.sources.map(esc).join('; '):'No supporting source'}</small></div>`);$('#queryInput').value='';$('#thread').scrollTop=$('#thread').scrollHeight};$('#rDate').value=now();render();
